[SerializeField] LayerMask hitMask;      // в инспекторе — список слоёв с галочками

[Flags] enum Status { None = 0, Burning = 1 << 0, Frozen = 1 << 1, Stunned = 1 << 2 }

bool Hits(GameObject go) => (hitMask.value & (1 << go.layer)) != 0;

void Fire(Ray ray) {
    int enemies = 1 << LayerMask.NameToLayer("Enemy");          // номер → маска
    if (Physics.Raycast(ray, out RaycastHit hit, 100f, enemies)) { /* … */ }
    Status s = Status.Burning | Status.Stunned;                 // 0b101
    bool stunned = (s & Status.Stunned) != 0;                   // без HasFlag
}

