public int HammingWeight(int n) {
    uint x = (uint)n;              // те же 32 бита, но без знака
    int count = 0;
    while (x != 0) {               // у uint сдвиг вдвигает нули — цикл кончится
        count += (int)(x & 1);     // младший бит
        x >>= 1;
    }
    return count;                  // до 32 шагов, даже если единица одна — в бите 31
}

