static int PopCountSwar(uint x) {
    x = x - ((x >> 1) & 0x55555555);                 // в каждой паре битов — сумма пары
    x = (x & 0x33333333) + ((x >> 2) & 0x33333333);  // в каждой четвёрке — сумма четвёрки
    x = (x + (x >> 4)) & 0x0F0F0F0F;                 // в каждом байте — сумма байта
    return (int)((x * 0x01010101) >> 24);            // умножение складывает байты в старший
}
